mapper.select:
SELECT t.status AS tabFlag, COUNT(t.id) AS count FROM dmp_output_task_record t WHERE t.is_deleted = false
${permissionSql}
GROUP BY t.status

SELECT t.id, l.name AS sourcePlatformName, i.name AS targetPlatformName, k.name AS sourceTypeName, t.source_code AS sourceCode, t.status AS status, t.create_time, t.update_time AS lastSyncTime, t.response_data AS returnMsg, t.is_need_sync AS isNeedSync, CASE WHEN dcob.id IS NOT NULL and dcob.field_value != '' THEN TRUE ELSE FALSE END AS isBlack FROM dmp_output_task_record t LEFT JOIN dmp_output_task g ON t.main_id = g.id LEFT JOIN dmp_cfg_output h ON g.cfg_output_id = h.id LEFT JOIN dmp_cfg_input_convert j ON h.input_convert_id = j.id LEFT JOIN dmp_cfg_input k ON j.main_id = k.id LEFT JOIN dmp_basic_system l ON k.system_id = l.id LEFT JOIN dmp_basic_system i ON h.system_id = i.id LEFT JOIN dmp_cfg_output_black dcob ON t.source_code = dcob.field_value AND h.id = dcob.main_id AND dcob.is_deleted = FALSE WHERE ${params.sqlMap.default} AND t.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc

SELECT t.id, l.name AS sourcePlatformName, i.name AS targetPlatformName, k.name AS sourceTypeName, t.source_code AS sourceCode, t.status AS status, t.create_time, t.update_time AS lastSyncTime, t.response_data AS returnMsg, t.is_need_sync AS isNeedSync, CASE WHEN dcob.id IS NOT NULL and dcob.field_value != '' THEN TRUE ELSE FALSE END AS isBlack FROM dmp_output_task_record_his t LEFT JOIN dmp_output_task_his g ON t.main_id = g.id LEFT JOIN dmp_cfg_output h ON g.cfg_output_id = h.id LEFT JOIN dmp_cfg_input_convert j ON h.input_convert_id = j.id LEFT JOIN dmp_cfg_input k ON j.main_id = k.id LEFT JOIN dmp_basic_system l ON k.system_id = l.id LEFT JOIN dmp_basic_system i ON h.system_id = i.id LEFT JOIN dmp_cfg_output_black dcob ON t.source_code = dcob.field_value AND h.id = dcob.main_id AND dcob.is_deleted = FALSE WHERE ${params.sqlMap.default} AND t.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc

select t.id,t.create_time, l.name AS sourcePlatformName, i.name AS targetPlatformName, k.name AS sourceTypeName, t.field_value AS sourceCode, t.status AS status, t.update_time AS lastSyncTime, ('黑名单原因：' || t.remark) AS returnMsg, t.is_need_sync AS isNeedSync, TRUE isBlack from (select id,main_id,create_time,field_value,remark,cfg_output_id,source_code,t4.update_time,status,is_need_sync from dmp_cfg_output_black t1 left join (select t2.is_need_sync,t3.cfg_output_id,t2.source_code,t2.update_time,t2.status from dmp_output_task_record t2 left join dmp_output_task t3 on t2.main_id = t3.id where t2.is_deleted = false and t3.is_deleted = false) t4 on t1.main_id = t4.cfg_output_id and t1.field_value = t4.source_code where t1.field_value != '' and t1.compare_sign = 'eq' and t1.is_web_add = true and t1.is_deleted = false) t LEFT JOIN dmp_cfg_output h ON t.main_id = h.id LEFT JOIN dmp_cfg_input_convert j ON h.input_convert_id = j.id LEFT JOIN dmp_cfg_input k ON j.main_id = k.id LEFT JOIN dmp_basic_system l ON k.system_id = l.id LEFT JOIN dmp_basic_system i ON h.system_id = i.id where ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc

SELECT t.id, l."name" AS sourcePlatformName, i.name AS targetPlatformName, k.name AS sourceTypeName, t.source_code AS sourceCode, t.status AS status, t.create_time, t.update_time AS lastSyncTime, t.response_data AS returnMsg, t.is_need_sync AS isNeedSync FROM dmp_output_task_record t LEFT JOIN dmp_output_task g ON t.main_id = g.id LEFT JOIN dmp_cfg_output h ON g.cfg_output_id = h.id LEFT JOIN dmp_cfg_input_convert j ON h.input_convert_id = j.id LEFT JOIN dmp_cfg_input k ON j.main_id = k.id LEFT JOIN dmp_basic_system l ON k.system_id = l.id LEFT JOIN dmp_basic_system i ON h.system_id = i.id LEFT JOIN dmp_push_msg m ON t.data_id = m.id WHERE t.is_deleted = false and t.status in('cosumererror','mqerror','error')
and m.source_id = #{params.sourceId}
and l."name" = #{params.sourcePlatformName}
and i.name = #{params.targetPlatformName}
order by t.id asc limit 1

mapper.delete:
insert into dmp_input_task_file_his select * from dmp_input_task_file where main_id in (${conditionSql});
delete from dmp_input_task_file where main_id in (${conditionSql});

insert into dmp_input_task_his select * from dmp_input_task where id in (${conditionSql});
delete from dmp_input_task where id in (${conditionSql});

insert into dmp_push_msg_his select * from dmp_push_msg where id in (select data_id from dmp_output_task_record where status = 'finish' and main_id in (${conditionSql}));
delete from dmp_push_msg where id in (select data_id from dmp_output_task_record where status = 'finish' and main_id in (${conditionSql}));

insert into dmp_output_task_record_his select * from dmp_output_task_record where status = 'finish' and main_id in (${conditionSql});
delete from dmp_output_task_record where status = 'finish' and main_id in (${conditionSql});

insert into dmp_output_task_his select * from dmp_output_task t where id in (${conditionSql});
delete from dmp_output_task where id in (${conditionSql});

mapper.select:
SELECT t.id, l."name" AS sourcePlatformName, i.name AS targetPlatformName, k.name AS sourceTypeName, t.source_code AS sourceCode, t.status AS status, t.create_time, t.update_time AS lastSyncTime, t.response_data AS returnMsg, t.is_need_sync AS isNeedSync FROM dmp_output_task_record t LEFT JOIN dmp_output_task g ON t.main_id = g.id LEFT JOIN dmp_cfg_output h ON g.cfg_output_id = h.id LEFT JOIN dmp_cfg_input_convert j ON h.input_convert_id = j.id LEFT JOIN dmp_cfg_input k ON j.main_id = k.id LEFT JOIN dmp_basic_system l ON k.system_id = l.id LEFT JOIN dmp_basic_system i ON h.system_id = i.id LEFT JOIN dmp_push_msg m ON t.data_id = m.id WHERE t.is_deleted = false and t.status in('finish')
and m.source_id = #{params.sourceId}
and i.code = #{params.targetPlatform}
order by t.id asc limit 1

SELECT sourceId, updateTime, status, returnMsg FROM ( SELECT m.source_id AS sourceId, t.update_time AS updateTime, t.status, t.response_data AS returnMsg, ROW_NUMBER() OVER ( PARTITION BY m.source_id ORDER BY t.create_time DESC ) AS rn FROM dmp_output_task_record t INNER JOIN dmp_push_msg m ON t.data_id = m.id WHERE ${params.sqlMap.dmp} AND t.is_deleted = false AND m.target_platform IN
#{item}
AND m.source_type IN
#{item}
AND m.source_id IN
#{item}
) AS sub WHERE rn = 1 ORDER BY updateTime DESC, sourceId

SELECT s.*,m.source_id from dmp_push_msg m inner join dmp_output_task_record s on m.id = s.data_id where m.source_type = #{sourceType} and m.source_id in
#{item}
and m.is_deleted = false and s.is_deleted = false ORDER BY s.id, s.create_time desc LIMIT 1
